import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { deleteAnnouncementHandler } from "../handlers/deleteAnnouncementHandler";
import type { ApiError } from "../runtime/client";
import type { TeamPartition } from "../types/TeamPartition";

type Data = Awaited<ReturnType<typeof deleteAnnouncementHandler>>;
type Vars = { teamPk: TeamPartition; announcementId: string };

export function useDeleteAnnouncement(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => deleteAnnouncementHandler(vars.teamPk, vars.announcementId),
    ...options,
  });
}
